questionvariables.text:
/* Class widths and frequency densities [width, freq den] */

narrowRange:[rand(6)+3, rand(3)+12];
wideRange:[rand(21)+30, rand(3)+3];

medRangeWidths: random_permutation([rand(11)+5, rand(11)+10, rand(11)+15]);
medRangeHeights: [rand(2)+6, rand(2)+8, rand(2)+10];

medRanges:[[first(medRangeWidths), first(medRangeHeights)], [second(medRangeWidths), second(medRangeHeights)], [third(medRangeWidths), third(medRangeHeights)]];

widthList: random_permutation(append([narrowRange], [wideRange], medRanges));

/* Each range given as [min, max, freq den] */

data: [[0, first(first(widthList)), second(first(widthList))], [first(first(widthList)), first(first(widthList))+first(second(widthList)), second(second(widthList))], [first(first(widthList))+first(second(widthList)), first(first(widthList))+first(second(widthList))+first(third(widthList)), second(third(widthList))], [first(first(widthList))+first(second(widthList))+first(third(widthList)), first(first(widthList))+first(second(widthList))+first(third(widthList))+first(fourth(widthList)), second(fourth(widthList))], [first(first(widthList))+first(second(widthList))+first(third(widthList))+first(fourth(widthList)), first(first(widthList))+first(second(widthList))+first(third(widthList))+first(fourth(widthList))+first(fifth(widthList)), second(fifth(widthList))], [first(first(widthList))+first(second(widthList))+first(third(widthList))+first(fourth(widthList))+first(fifth(widthList)), 120, rand(3)+1]];

/* Solutions */

tans1: third(first(data))*first(first(widthList));
tans2: third(first(data));
tans3: third(second(data))*first(second(widthList));
tans4: third(second(data));
tans5: third(third(data))*first(third(widthList));
tans6: third(third(data));
tans7: third(fourth(data))*first(fourth(widthList));
tans8: third(fourth(data));
tans9: third(fifth(data))*first(fifth(widthList));
tans10: third(fifth(data));
tans11: third(sixth(data))*(120-first(sixth(data)));
tans12: third(sixth(data));

tans13: third(first(data))*first(first(widthList)) + third(second(data))*first(second(widthList)) + third(third(data))*first(third(widthList)) + third(fourth(data))*first(fourth(widthList)) + third(fifth(data))*first(fifth(widthList)) + third(sixth(data))*(120-first(sixth(data)));

tans14: if second(first(data))>60 then (second(first(data))-60)*tans2+tans3+tans5+tans7+tans9+tans11 else if second(second(data))>60 then (second(second(data))-60)*tans4+tans5+tans7+tans9+tans11 else if second(third(data))>60 then (second(third(data))-60)*tans6+tans7+tans9+tans11 else if second(fourth(data))>60 then (second(fourth(data))-60)*tans8+tans9+tans11 else if second(fifth(data))>60 then (second(fifth(data))-60)*tans10+tans11 else if second(sixth(data))>60 then 60*tans12;

